mapper.select:
SELECT * FROM sys_user WHERE role <> #{adminRole}
AND deleted = false
ORDER BY deleted DESC, create_time DESC

mapper.update:
UPDATE sys_user
SET deleted = true,
    deleted_time = #{deletedTime},
    disabled = true,
    disabled_time = #{deletedTime}
WHERE id = #{id}
  AND role <> #{adminRole}
  AND deleted = false
